import { Button } from "@/components/ui/button";
import { Reveal, RevealItem } from "@/components/ui/reveal";
import { DecorIcon } from "@/components/home/decor-icon";
import { FullWidthDivider } from "@/components/home/full-width-divider";
import Link from "next/link";

export function IntegrationsSection() {
  return (
    <section className="relative mb-24 lg:mb-48">
      <DecorIcon className="size-4" position="top-left" />
      <DecorIcon className="size-4" position="top-right" />
      <DecorIcon className="size-4" position="bottom-left" />
      <DecorIcon className="size-4" position="bottom-right" />
      <FullWidthDivider className="-top-px" />
      <FullWidthDivider className="-bottom-px" />

      <Reveal className="grid gap-6 p-4 md:grid-cols-2 lg:gap-12">
        <RevealItem className="flex flex-col justify-between gap-12 pb-6 max-lg:order-last md:mt-6">
          <div>
            <h2 className="max-w-4xl text-4xl font-medium tracking-tight text-balance text-muted-foreground">
              <span className="text-foreground">
                Integrate with your favorite tools.
              </span>
            </h2>
            <p className="mt-4 mb-6 text-lg text-balance text-muted-foreground">
              Connect seamlessly with popular platforms and services to enhance
              your workflow.
            </p>
            <Button variant="outline" asChild>
              <Link href="#">Get Started</Link>
            </Button>
          </div>

          <p className="max-w-xs text-lg text-balance text-muted-foreground">
            ClypAI integrates with{" "}
            <span className="font-medium text-foreground">over 150 tools</span>{" "}
            to enhance your workflow.
          </p>
        </RevealItem>

        <RevealItem className="mask-radial-at-top-left mask-radial-from-65% mask-radial-[100%_80%] -mx-6 px-6 sm:mx-auto sm:max-w-md md:-mx-6 md:ml-auto md:mr-0">
          <div className="bg-card rounded-2xl border p-3 shadow-lg md:pb-12">
            <div className="grid grid-cols-2 gap-2">
              <Integration
                icon={<YouTube />}
                name="YouTube"
                description="Publish and manage your clips on the world's largest video platform."
              />
              <Integration
                icon={<TikTok />}
                name="TikTok"
                description="Create and distribute short-form video content to a global audience."
              />
              <Integration
                icon={<Instagram />}
                name="Instagram"
                description="Share clips and reels directly with your Instagram audience."
              />
              <Integration
                icon={<LinkedIn />}
                name="LinkedIn"
                description="Publish professional video content to your LinkedIn network."
              />
              <Integration
                icon={<Snapchat />}
                name="Snapchat"
                description="Share Snaps and Spotlight content with your audience."
              />
              <Integration
                icon={<XLogo />}
                name="X"
                description="Post and share video clips directly on X."
              />
            </div>
          </div>
        </RevealItem>
      </Reveal>
    </section>
  );
}

const Integration = ({
  icon,
  name,
  description,
}: {
  icon: React.ReactNode;
  name: string;
  description: string;
}) => {
  return (
    <div className="hover:bg-foreground/5 cursor-pointer space-y-4 rounded-lg border p-4 transition-colors">
      <div className="flex size-fit items-center justify-center">{icon}</div>
      <div className="space-y-1">
        <h3 className="text-sm font-medium">{name}</h3>
        <p className="text-muted-foreground line-clamp-1 text-sm md:line-clamp-2">
          {description}
        </p>
      </div>
    </div>
  );
};

